import{_ as i,a0 as l,w as p,s as h,ao as r,I as o,x as t,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试 | LCTT x X-CMD","titleTemplate":false,"description":"Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20161010 Antergos – Best Arch based distro for beginners","title":"Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试","tag":"201610","desc":""},"relativePath":"201610/20161010 Antergos – Best Arch based distro for beginners.md","filePath":"[post].md"}'),d={name:"201610/20161010 Antergos – Best Arch based distro for beginners.md"};function g(m,e,c,w,u,x){const a=l("Link");return p(),h("div",null,[e[16]||(e[16]=r('<h1 id="antergos-基于-arch-发行版-想要尝试-arch-的绝对值得一试" tabindex="-1">Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试 <a class="header-anchor" href="#antergos-基于-arch-发行版-想要尝试-arch-的绝对值得一试" aria-label="Permalink to “Antergos：基于 Arch 发行版，想要尝试 Arch 的绝对值得一试”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>众所周知，Arch Linux 是最好的 Linux 发行版之一，我们可以随心所欲的进行定制。我们可以滚动式更新最新的软件，但它的安装和配置的过程对于初学者则相对困难。现在就让我来为你展示如何安装 Antergos，这个基于 Arch 的、给新手的最好发行版，要尝试 Arch 的用户可以试一试，我保证绝对值得一试。</p><p>Antergos 是一个滚动式更新的发行版，基于 Arch Linux 提供桌面环境，是集现代化、高雅和高效率于一体的操作系统。想要挑战一下安装 Arch Linux 的用户，都可以先试一试 Antergos。</p><p>由于是滚动式更新，当上游发布更新，你的整个系统 (包括系统组件和你已安装的应用) 就会升级到最新的滚动版本，仅仅稍微延期一点时间以确保系统的稳定。</p><p>Antergos 有多个语言版本，包括英语、西班牙语等版本，在安装时你可以在语言栏选择预置语言。默认的配置确保了开箱即用，不需要安装额外的软件就可以直接浏览网页、听音乐、看视频以及做任何你想做的事情。</p><p>Antergos 项目最初名字是 Cinnarch，并且只提供一个桌面环境。现在它有多个桌面环境（包括 Cinnamon、Gnome、KDE、MATE、Openbox 和 Xfce）以供用户在安装之时进行选择。同时，它还默认包含了著名的 Numix GTK 主题和 Icon 主题。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><h4 id="下载-antergos-linux" tabindex="-1">下载 Antergos Linux <a class="header-anchor" href="#下载-antergos-linux" aria-label="Permalink to “下载 Antergos Linux”">​</a></h4>',9)),o("p",null,[e[1]||(e[1]=t("访问 ",-1)),n(a,{href:"https://antergos.com/try-it/"},{default:s(()=>[...e[0]||(e[0]=[t("Antergos",-1)])]),_:1}),e[2]||(e[2]=t(" 下载页面，然后下载最新的 Live ISO 镜像。任何人都可以免费获取 Antergos 镜像，烧录到 CD/DVD 或者写到 USB 设备，开始 Antergos 之旅。",-1))]),e[17]||(e[17]=r('<h4 id="创建可启动-usb" tabindex="-1">创建可启动 USB <a class="header-anchor" href="#创建可启动-usb" aria-label="Permalink to “创建可启动 USB”">​</a></h4><p>下载好最新的 Antergos Live ISO 镜像之后，你需要使用命令行或者图形界面的方法来制作一个可启动介质。</p><h4 id="使用-antergos-安装介质来启动电脑" tabindex="-1">使用 Antergos 安装介质来启动电脑 <a class="header-anchor" href="#使用-antergos-安装介质来启动电脑" aria-label="Permalink to “使用 Antergos 安装介质来启动电脑”">​</a></h4><p>使用 Antergos 安装介质来启动电脑。成功启动到 Live ISO 之后，你会看到与下图相似的界面。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-1.png" alt=""></p><p>点击 Install It 按钮开始 Angergos 的安装过程。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-2.png" alt=""></p><h4 id="选择语系" tabindex="-1">选择语系 <a class="header-anchor" href="#选择语系" aria-label="Permalink to “选择语系”">​</a></h4><p>Antergos 的易于使用的图形安装器非常不错。此处选择你需要选用的语系并点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-3.png" alt=""></p><h4 id="系统检测" tabindex="-1">系统检测 <a class="header-anchor" href="#系统检测" aria-label="Permalink to “系统检测”">​</a></h4><p>请确保你有足够的磁盘空间，连接好电源以及连接到网络，点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-4.png" alt=""></p><h4 id="选择地点" tabindex="-1">选择地点 <a class="header-anchor" href="#选择地点" aria-label="Permalink to “选择地点”">​</a></h4><p>选择地点可以帮助决定系统所使用的本地化信息（locale）。通常是选择你所属的国家即可。这里有一个基于你选择的语言的位置的简短列表。点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-5.png" alt=""></p><h4 id="选择时区" tabindex="-1">选择时区 <a class="header-anchor" href="#选择时区" aria-label="Permalink to “选择时区”">​</a></h4><p>选择使用的时区，然后点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-6.png" alt=""></p><h4 id="选择键盘布局" tabindex="-1">选择键盘布局 <a class="header-anchor" href="#选择键盘布局" aria-label="Permalink to “选择键盘布局”">​</a></h4><p>选择你选用的键盘布局，然后点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-7.png" alt=""></p><h4 id="选择桌面环境" tabindex="-1">选择桌面环境 <a class="header-anchor" href="#选择桌面环境" aria-label="Permalink to “选择桌面环境”">​</a></h4><p>Antergos 提供了多个选择（包括 Cinnamon、Gnome、KDE、MATE、Openbox 和 Xfce），根据你的喜好进行选择即可。然后点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-8.png" alt=""></p><h4 id="gnome-–-特性选择" tabindex="-1">Gnome – 特性选择 <a class="header-anchor" href="#gnome-–-特性选择" aria-label="Permalink to “Gnome – 特性选择”">​</a></h4><p>这里我选择了默认的 Gnome 桌面环境，此处你可以选择需要额外安装的软件以及正确的驱动程序。然后点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-10.png" alt=""></p><h4 id="安装类型" tabindex="-1">安装类型 <a class="header-anchor" href="#安装类型" aria-label="Permalink to “安装类型”">​</a></h4><p>初次安装可以选择第一个选项（ Erase disk and install Antergos ）。然后点击 Next 按钮继续下一步。（LCTT 译注，但是要注意这个选项会擦除你的整个硬盘数据，如果你是全新安装，则可以使用该选项。）</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-11.png" alt=""></p><h4 id="自动安装模式" tabindex="-1">自动安装模式 <a class="header-anchor" href="#自动安装模式" aria-label="Permalink to “自动安装模式”">​</a></h4><p>这里会有一个檫除硬盘的警告，并选择安装 Grub 启动器，然后点击 Next 按钮继续下一步。</p><blockquote><p>WARNING ! This will overwrite everything currently on your drive !</p></blockquote><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-12.png" alt=""></p><h4 id="安装设置综述" tabindex="-1">安装设置综述 <a class="header-anchor" href="#安装设置综述" aria-label="Permalink to “安装设置综述”">​</a></h4><p>确认最后的安装设置概览，如地点、时区、键盘布局、桌面环境和特性，然后点击 Next 按钮继续下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-14.png" alt=""></p><h4 id="创建你的用户名" tabindex="-1">创建你的用户名 <a class="header-anchor" href="#创建你的用户名" aria-label="Permalink to “创建你的用户名”">​</a></h4><p>此时需要为你的系统创建一个新用户名和对应的密码，然后点击 Next 按钮继续下一步。</p><ul><li>你的昵称</li><li>电脑名称</li><li>用户名</li><li>设置密码</li><li>密码二次确认</li><li>选择“登录系统需要密码”</li></ul><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-15.png" alt=""></p><h4 id="安装进程" tabindex="-1">安装进程 <a class="header-anchor" href="#安装进程" aria-label="Permalink to “安装进程”">​</a></h4><p>此时就是等待 Antergos 安装完成。安装好之后，移除安装介质在点击“立刻重启”按钮。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-16.png" alt=""></p><h4 id="输入用户名和密码" tabindex="-1">输入用户名和密码 <a class="header-anchor" href="#输入用户名和密码" aria-label="Permalink to “输入用户名和密码”">​</a></h4><p>这是欢迎界面，输入密码即可登录：</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-17.png" alt=""></p><p>发行信息截图：</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-18.png" alt=""></p><p>我们还会提供了一些列循序渐进的 Linux 系统管理的相关文章。如果本文对你有用，请花费几分钟分享你得想法到评论区。</p><p>请于我们保持联系，祝君好运！</p><hr>',53)),o("p",null,[e[4]||(e[4]=t("via: ",-1)),n(a,{href:"http://www.2daygeek.com/how-to-install-antergos-linux/"},{default:s(()=>[...e[3]||(e[3]=[t("http://www.2daygeek.com/how-to-install-antergos-linux/",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("作者：",-1)),n(a,{href:"http://www.2daygeek.com/author/magesh/"},{default:s(()=>[...e[5]||(e[5]=[t("MAGESH MARUTHAMUTHU",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),n(a,{href:"https://github.com/GHLandy"},{default:s(()=>[...e[6]||(e[6]=[t("GHLandy",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const f=i(d,[["render",g]]);export{b as __pageData,f as default};
